/// Any other architecture: no table, so no filter can be built and the launcher
/// refuses rather than installing something it cannot reason about.
#[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
pub const TABLE: &[(&str, u32)] = &[];

/// Number of `name` on this architecture, or `None` when it does not exist here.
pub fn number(name: &str) -> Option<u32> {
    TABLE
        .binary_search_by_key(&name, |(n, _)| n)
        .ok()
        .map(|i| TABLE[i].1)
}

/// Whether this architecture is one Zygo can build a filter for.
pub fn is_supported() -> bool {
    !TABLE.is_empty() && AUDIT_ARCH != 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_for_binary_search() {
        for pair in TABLE.windows(2) {
            assert!(pair[0].0 < pair[1].0, "{} then {}", pair[0].0, pair[1].0);
        }
    }

    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    #[test]
    fn the_syscalls_every_sandbox_needs_are_present() {
        for name in [
            "read",
            "write",
            "openat",
            "close",
            "mmap",
            "mprotect",
            "munmap",
            "clone",
            "execve",
            "exit_group",
            "futex",
            "rt_sigaction",
        ] {
            assert!(number(name).is_some(), "{name} missing from the table");
        }
    }

    /// Spot checks against values that have been stable since the ABI was
    /// frozen, so a table regenerated for the wrong architecture is caught.
    #[cfg(target_arch = "aarch64")]
    #[test]
    fn numbers_match_the_aarch64_abi() {
        assert_eq!(number("read"), Some(63));
        assert_eq!(number("openat"), Some(56));
        assert_eq!(number("execve"), Some(221));
        assert_eq!(number("clone"), Some(220));
        assert_eq!(number("open"), None, "arm64 has no legacy open");
        assert_eq!(number("select"), None, "arm64 has no legacy select");
    }

    #[cfg(target_arch = "x86_64")]
    #[test]
    fn numbers_match_the_x86_64_abi() {
        assert_eq!(number("read"), Some(0));
        assert_eq!(number("write"), Some(1));
        assert_eq!(number("open"), Some(2));
        assert_eq!(number("execve"), Some(59));
        assert_eq!(number("clone"), Some(56));
    }

    #[test]
    fn an_unknown_name_resolves_to_nothing() {
        assert_eq!(number("definitely_not_a_syscall"), None);
    }
}
